package com.ruoyi.web.biz;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.transaction.support.TransactionSynchronization;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.access.AccessDeniedException;
import com.ruoyi.common.utils.SecurityUtils;
import com.ruoyi.common.exception.ServiceException;
import com.ruoyi.common.core.redis.RedisCache;
import com.ruoyi.common.core.domain.model.LoginUser;
import com.ruoyi.framework.web.service.PermissionService;
@Service
public class EmployeeService {
 final JdbcTemplate db; final BizMapper scope; final PermissionService permission; final RedisCache cache;
 public EmployeeService(CompanyOnboardingMapper m,BizMapper s,PermissionService p,RedisCache c){db=m.database();scope=s;permission=p;cache=c;}
 public boolean hasPermission(String p){return permission.hasPermi(p);}
 public Long userCompany(long user){return scope.company(user);}
 long uid(){return SecurityUtils.getUserId();}
 void perm(String key){if(!permission.hasPermi("biz:employee:"+key))throw new AccessDeniedException("没有员工业务权限");}
 boolean hasRole(long id,String role){return db.queryForObject("SELECT COUNT(*) FROM sys_user_role u JOIN sys_role r ON r.role_id=u.role_id WHERE u.user_id=? AND r.role_key=? AND r.status='0' AND r.del_flag='0'",Long.class,id,role)>0;}
 long manager(String action){perm(action);if(!hasRole(uid(),"company_admin")&&!hasRole(uid(),"company_hr"))throw new AccessDeniedException("仅本企业管理员或人事可操作");Long company=scope.company(uid());if(company==null)throw new AccessDeniedException("企业归属无效");return company;}
 void lock(long user){if(db.queryForList("SELECT user_id FROM sys_user WHERE user_id=? AND status='0' AND del_flag='0' FOR UPDATE",user).isEmpty())throw new ServiceException("账号不可用",409);}
 void unbound(long user){if(db.queryForObject("SELECT COUNT(*) FROM biz_company_user WHERE user_id=? AND status='ACTIVE'",Long.class,user)>0)throw new ServiceException("账号已有企业归属",409);}
 void active(long company){if(db.queryForObject("SELECT COUNT(*) FROM biz_company WHERE id=? AND status='ACTIVE'",Long.class,company)!=1)throw new ServiceException("企业不存在或已停用",400);}
 void valid(EmployeeInput in){if(in.realName()==null||in.realName().isBlank()||in.realName().length()>50||in.contactPhone()==null||!in.contactPhone().matches("[0-9+() -]{6,30}")||in.jobTitle()!=null&&in.jobTitle().length()>80)throw new ServiceException("姓名、电话或岗位无效",400);}
 Map<String,Object> application(long id,boolean forUpdate){var rows=db.queryForList("SELECT * FROM biz_employee_apply WHERE id=?"+(forUpdate?" FOR UPDATE":""),id);if(rows.isEmpty())throw new ServiceException("申请不存在",404);return rows.get(0);}
 void owner(Map<String,Object> a){if(((Number)a.get("user_id")).longValue()!=uid())throw new AccessDeniedException("仅申请人可操作");}
 void invalidate(long user){TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){@Override public void afterCommit(){Collection<String> keys=cache.keys("login_tokens:*");for(String key:keys){LoginUser login=cache.getCacheObject(key);if(login!=null&&Long.valueOf(user).equals(login.getUserId()))cache.deleteObject(key);}}});}
 public List<Map<String,Object>> companies(){perm("apply");return db.queryForList("SELECT id,company_name FROM biz_company WHERE status='ACTIVE' ORDER BY id DESC LIMIT 500");}
 public List<Map<String,Object>> applications(boolean review){if(review){long company=manager("review");return db.queryForList("SELECT * FROM biz_employee_apply WHERE company_id=? ORDER BY id DESC LIMIT 200",company);}perm("apply");return db.queryForList("SELECT a.*,c.company_name FROM biz_employee_apply a JOIN biz_company c ON c.id=a.company_id WHERE a.user_id=? ORDER BY a.id DESC LIMIT 200",uid());}
 public Map<String,Object> detail(long id){var a=application(id,false);if(((Number)a.get("user_id")).longValue()!=uid()){long company=manager("review");if(company!=((Number)a.get("company_id")).longValue())throw new AccessDeniedException("禁止查看其他企业申请");}a.put("audits",db.queryForList("SELECT round_no,to_status,opinion,reviewed_at FROM biz_audit_record WHERE business_type='employee_apply' AND business_id=? ORDER BY round_no",id));return a;}
 @Transactional public long save(Long id,EmployeeInput in){perm("apply");valid(in);if(in.companyId()==null)throw new ServiceException("请选择企业",400);active(in.companyId());lock(uid());unbound(uid());if(id==null){if(db.queryForObject("SELECT COUNT(*) FROM biz_employee_apply WHERE user_id=? AND status IN ('DRAFT','PENDING')",Long.class,uid())>0)throw new ServiceException("请先处理已有申请",409);db.update("INSERT INTO biz_employee_apply(company_id,user_id,real_name,contact_phone,job_title,status,create_by) VALUES(?,?,?,?,?,'DRAFT',?)",in.companyId(),uid(),in.realName(),in.contactPhone(),in.jobTitle(),SecurityUtils.getUsername());return db.queryForObject("SELECT id FROM biz_employee_apply WHERE user_id=? AND status='DRAFT'",Long.class,uid());}
 var a=application(id,true);owner(a);if(!Set.of("DRAFT","REJECTED").contains(a.get("status")))throw new ServiceException("当前状态不可修改",409);if(in.companyId()!=((Number)a.get("company_id")).longValue())throw new ServiceException("不可变更申请企业",400);if(in.version()==null||db.update("UPDATE biz_employee_apply SET real_name=?,contact_phone=?,job_title=?,version=version+1,update_by=? WHERE id=? AND version=?",in.realName(),in.contactPhone(),in.jobTitle(),SecurityUtils.getUsername(),id,in.version())!=1)throw new ServiceException("版本冲突",409);return id;}
 @Transactional public void submit(long id){perm("apply");var a=application(id,true);owner(a);if(!Set.of("DRAFT","REJECTED").contains(a.get("status")))throw new ServiceException("当前状态不可提交",409);lock(uid());unbound(uid());active(((Number)a.get("company_id")).longValue());db.update("UPDATE biz_employee_apply SET round_no=round_no+IF(status='REJECTED',1,0),status='PENDING',version=version+1,update_by=? WHERE id=?",SecurityUtils.getUsername(),id);}
 @Transactional public void review(long id,boolean approved,String opinion){long company=manager("review");if(opinion==null||opinion.isBlank()||opinion.length()>500)throw new ServiceException("审核意见必填且不超过500字",400);var a=application(id,true);if(company!=((Number)a.get("company_id")).longValue())throw new AccessDeniedException("不能审核其他企业");long user=((Number)a.get("user_id")).longValue();if(user==uid())throw new AccessDeniedException("禁止自审");if(!"PENDING".equals(a.get("status")))throw new ServiceException("不在待审核状态",409);lock(user);active(company);
 if(approved){unbound(user);db.update("INSERT INTO biz_company_user(company_id,user_id,status) VALUES(?,?,'ACTIVE') ON DUPLICATE KEY UPDATE status='ACTIVE'",company,user);db.update("INSERT INTO biz_employee_info(company_id,user_id,employee_no,real_name,contact_phone,job_title,entry_date,status,create_by) VALUES(?,?,?,?,?,?,CURRENT_DATE,'ACTIVE',?) ON DUPLICATE KEY UPDATE real_name=VALUES(real_name),contact_phone=VALUES(contact_phone),job_title=VALUES(job_title),entry_date=CURRENT_DATE,leave_date=NULL,status='ACTIVE',version=version+1",company,user,"EMP-"+user,a.get("real_name"),a.get("contact_phone"),a.get("job_title"),SecurityUtils.getUsername());db.update("DELETE ur FROM sys_user_role ur JOIN sys_role r ON r.role_id=ur.role_id WHERE ur.user_id=? AND r.role_key IN ('company_admin','company_hr','company_business','company_finance','employee')",user);db.update("INSERT IGNORE INTO sys_user_role(user_id,role_id) SELECT ?,role_id FROM sys_role WHERE role_key='employee' AND status='0' AND del_flag='0'",user);if(!hasRole(user,"employee"))throw new ServiceException("员工角色配置缺失",409);invalidate(user);}
 String state=approved?"APPROVED":"REJECTED";db.update("UPDATE biz_employee_apply SET status=?,version=version+1,update_by=? WHERE id=?",state,SecurityUtils.getUsername(),id);db.update("INSERT INTO biz_audit_record(company_id,business_type,business_id,round_no,applicant_id,reviewer_id,from_status,to_status,opinion,status) VALUES(?,'employee_apply',?,?,?,?,'PENDING',?,?,'RECORDED')",company,id,a.get("round_no"),user,uid(),state,opinion);}
 public List<Map<String,Object>> staff(){long company=manager("manage");return db.queryForList("SELECT * FROM biz_employee_info WHERE company_id=? ORDER BY id DESC LIMIT 200",company);}
 public Map<String,Object> staffDetail(long id){long company=manager("manage");var rows=db.queryForList("SELECT * FROM biz_employee_info WHERE company_id=? AND id=?",company,id);if(rows.isEmpty())throw new ServiceException("员工不存在或无权访问",404);return rows.get(0);}
 public Map<String,Object> me(){perm("profile");Long company=scope.company(uid());if(company==null)throw new AccessDeniedException("尚未加入有效企业");return db.queryForMap("SELECT * FROM biz_employee_info WHERE company_id=? AND user_id=? AND status='ACTIVE'",company,uid());}
 @Transactional public void update(long id,EmployeeInput in,boolean personal){valid(in);Map<String,Object> old=personal?me():staffDetail(id);long realId=((Number)old.get("id")).longValue();if(personal&&id!=realId)throw new AccessDeniedException("仅可修改本人资料");if(!personal&&(hasRole(((Number)old.get("user_id")).longValue(),"company_admin")||hasRole(((Number)old.get("user_id")).longValue(),"platform_admin")))throw new AccessDeniedException("管理员档案请由本人维护");if(!"ACTIVE".equals(old.get("status")))throw new ServiceException("离职档案不可修改",409);
 int changed;if(personal)changed=db.update("UPDATE biz_employee_info SET real_name=?,contact_phone=?,version=version+1,update_by=? WHERE id=? AND company_id=? AND version=?",in.realName(),in.contactPhone(),SecurityUtils.getUsername(),id,old.get("company_id"),in.version());else {if(in.employeeNo()==null||in.employeeNo().isBlank()||in.employeeNo().length()>40)throw new ServiceException("工号必填且不超过40字符",400);changed=db.update("UPDATE biz_employee_info SET real_name=?,contact_phone=?,job_title=?,employee_no=?,version=version+1,update_by=? WHERE id=? AND company_id=? AND version=?",in.realName(),in.contactPhone(),in.jobTitle(),in.employeeNo(),SecurityUtils.getUsername(),id,old.get("company_id"),in.version());}if(changed!=1)throw new ServiceException("版本冲突",409);}
 @Transactional public void roles(long id,List<String> requested){long company=manager("roles");if(!hasRole(uid(),"company_admin"))throw new AccessDeniedException("仅企业管理员可授权");if(requested==null||requested.isEmpty()||!Set.of("employee","company_hr","company_business","company_finance").containsAll(requested))throw new ServiceException("只能授予指定企业业务角色",400);var target=staffDetail(id);long user=((Number)target.get("user_id")).longValue();lock(user);if(user==uid()||hasRole(user,"company_admin")||hasRole(user,"platform_admin")||user==1||!"ACTIVE".equals(target.get("status"))||!Long.valueOf(company).equals(scope.company(user)))throw new AccessDeniedException("不能修改该账号角色");db.update("DELETE ur FROM sys_user_role ur JOIN sys_role r ON r.role_id=ur.role_id WHERE ur.user_id=? AND r.role_key IN ('employee','company_hr','company_business','company_finance')",user);Set<String> roles=new HashSet<>(requested);roles.add("employee");for(String role:roles){int n=db.update("INSERT INTO sys_user_role(user_id,role_id) SELECT ?,role_id FROM sys_role WHERE role_key=? AND status='0' AND del_flag='0'",user,role);if(n!=1)throw new ServiceException("角色配置异常",409);}invalidate(user);}
}
